#!/usr/bin/env python3
"""Build the portable manual Marketing launch Module using existing AM bricks."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
DEST=(ROOT.parents[1] / 'marketing-launch')/'agents/main'
BROKER='recipe--application_data_v1'
DOMAIN=(ROOT/'domain.js').read_text().replace('export ','')
RUNTIME=(ROOT/'runtime.js').read_text()
OPS={'campaign-save':("Marketing — campaign",'campaign','cib_marketing'),'content-link':("Marketing — link evidence and content",'content','cib_marketing'),'request':("Marketing — trial request",'request','cib_marketing'),'progress':("Support — trial progress",'support','cib_service_client'),'read':("Marketing — read a record",None,'cib_dossiers'),'list':("Marketing — accessible list",None,'cib_dossiers'),'people':("Marketing — eligible members",None,'cib_dossiers'),'share':("Marketing — share or revoke access",'sharing','cib_dossiers'),'summary':("Management — launch and first results",'direction','cib_direction')}
OPTIONS={'jeu':[('usage',"Real work"),('qualification',"Synthetic trials")],'kind':[('campaign',"Campaign"),('trial',"Trial")],'permission':[('read',"Read"),('write',"Write"),('none',"Revoke")],'phase':[('en_cours',"In progress"),('bloque',"Blocked"),('premier_resultat_confirme',"First result confirmed (internal attestation)")],'confirmation_manuelle':[('non',"No"),('oui',"Yes")],'confirmation_resultat':[('non',"No"),('oui',"Yes, statement and evidence reviewed")]}
TITLES={'jeu':"Data set",'campaign_id':"Campaign ID",'trial_id':"Trial ID",'id':"Record ID",'kind':"Record type",'objectif':"Objective",'audience':"Target audience",'promesse':"Message and bounded promise",'canal':"Planned channel (no distribution)",'responsable':"Operational owner",'echeance':"Deadline (YYYY-MM-DD)",'critere_fin':"First-result criterion",'expected_revision':"Expected revision",'campaign_revision':"Campaign revision",'veille_ref':"Watch record",'veille_revision':"Watch revision",'contenu_ref':"Content record",'contenu_revision':"Content revision",'preuve_ref':"Review evidence reference",'personne_ref':"Internal person reference",'besoin':"Declared need",'phase':"Trial stage",'accompagnement_ref':"Support record",'accompagnement_revision':"Support revision",'date_confirmation':"Statement date (YYYY-MM-DD)",'confirmation_resultat':"First result declared and evidence reviewed",'subject_user_id':"Existing member",'permission':"Permission on this record",'confirmation_manuelle':"I confirm this internal operation"}
MEMOS={'objectif','audience','promesse','critere_fin','besoin'}
FIELDS={'campaign':['jeu','campaign_id','objectif','audience','promesse','canal','responsable','echeance','critere_fin','expected_revision','confirmation_manuelle'],'content':['jeu','campaign_id','expected_revision','veille_ref','veille_revision','contenu_ref','contenu_revision','preuve_ref','confirmation_manuelle'],'request':['jeu','campaign_id','campaign_revision','trial_id','personne_ref','besoin','objectif','confirmation_manuelle'],'support':['jeu','trial_id','expected_revision','phase','accompagnement_ref','accompagnement_revision','date_confirmation','confirmation_resultat','confirmation_manuelle'],'sharing':['jeu','kind','id','expected_revision','subject_user_id','permission','confirmation_manuelle'],'direction':['jeu']}
OPTIONAL={'date_confirmation'}
MAP={'campaign':'campaign-save','content':'content-link','request':'request','support':'progress','sharing':'share','direction':'summary'}
def dump(path,value):path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
def field(name):
    f={'name':name,'title':TITLES[name],'type':'select' if name in OPTIONS else 'text' if name in MEMOS else 'string','required':name not in OPTIONAL,'default':'{{ state.selected.prefill.'+name+' }}'}
    if name in OPTIONS:f['options']=[{'value':v,'label':l} for v,l in OPTIONS[name]]
    return f
OUTPUTS=['record','revision','owner_user_id','permissions','permissions_summary','shares','share_count','rows','items','people','selected_target','summary','prefill','effects','replayed','message','scope','validation_mode','external_effect']
def workflow(op):
    title,form,role=OPS[op]
    w={'$schema':'agentmaurice.workflow/v2','schema_version':2,'kind':'workflow','workflow_id':'cib-launch-'+op,'version':'2','title':title,'description':"Internal manual workflow; data and permissions are controlled by the existing AM broker.",'actions':[{'id':'run','type':'code_execution','context':{'allowed_tools':[BROKER]},'code':"import { callTool } from './tools/nats_bridge.ts';\nconst input={{ json . }};\n"+DOMAIN+'\n'+RUNTIME+"\nreturn await execute('"+op+"',input);",'output_key':'result'}],'output':{k:'{{ result.'+k+' }}' for k in OUTPUTS}}
    if form:w['forms']=[{'id':form,'title':title,'fields':[field(n) for n in FIELDS[form]],'actions_on_submit':['run']}]
    return w
GUIDES={'campaign':"1. Create a campaign. The ID and data set are stable; enter 0 on creation. Editing the brief returns content to review.",'content':"2. Prepare Watch and Content records in the existing roles. Select a campaign, then link their exact IDs and revisions with review evidence. No publication.",'request':"3. Select a ready campaign, then record a request with a stable trial ID. An identical replay creates no duplicate. Share the trial record for editing with the support person.",'support':"4. Support prepares its existing record. Select the explicitly shared trial, mark it in progress, then link the declared result, evidence and date. An internal statement proves neither sale nor publication.",'sharing':"Share one record: select it, load members, then select a person to open the form. Use Revoke to remove access. Sharing does not grant service use or sharing administration.",'direction':"5. This summary counts only records you can access. Requests and first results are distinct. Attribution, conversion and time savings remain unmeasured."}
def miniapp(form):
    defaults={n:'' for n in FIELDS[form]};defaults.update({'jeu':'usage','expected_revision':'0','campaign_revision':'0','confirmation_manuelle':'non','confirmation_resultat':'non','permission':'read','kind':'campaign','phase':'en_cours'})
    events=[];layout=[{'type':'text','value':GUIDES[form]},{'type':'text','value':"Open the form by its title in the available interactions. Long fields are notes. The named owner grants no AM permissions."}]
    for game,label in [('usage',"Refresh real work"),('qualification',"Refresh trials")]:
        eid='refresh-'+game;layout.append({'type':'button','label':label,'on_click':eid});events.append({'event_id':eid,'trigger':'action.click','workflow':{'workflow_id':'cib-launch-'+('summary' if form=='direction' else 'list'),'input':{'jeu':game,'kind':'trial' if form=='support' else 'campaign' if form in ['campaign','content'] else 'all'}},'result_to_state':'listing'})
    layout += [{'type':'text','value':{'state':'listing.message'}},{'type':'table','columns':['kind_label','id','phase_label','revision','objectif'],'column_labels':{'kind_label':'Type','id':'ID','phase_label':'Stage','revision':'Revision','objectif':'Objective'},'rows':{'state':'listing.items'},**({} if form=='direction' else {'on_row_click':'select'})}]
    if form!='direction':
        events.append({'event_id':'select','trigger':'table.row_click','workflow':{'workflow_id':'cib-launch-read','input':{'jeu':'{{ event.payload.item.jeu }}','kind':'{{ event.payload.item.kind }}','id':'{{ event.payload.item.id }}','form_id':form}},'result_to_state':'selected'})
        layout += [{'type':'text','value':{'state':'selected.message'}},{'type':'text','value':{'state':'selected.permissions_summary'}},{'type':'text','value':{'state':'selected.record.objectif'}},{'type':'text','value':{'state':'selected.record.resultat_observe'}},{'type':'text','value':{'state':'selected.record.preuve_ref'}}]
    if form=='sharing':
        layout += [{'type':'button','label':"Load existing members",'on_click':'people'},{'type':'table','columns':['user_id','display_name'],'column_labels':{'user_id':'Identifier','display_name':'Member'},'rows':{'state':'people.people'},'on_row_click':'choose'}]
        base={'jeu':'{{ state.selected.record.jeu }}','kind':'{{ state.selected.record.kind }}','id':'{{ state.selected.record.id }}'}
        events += [{'event_id':'people','trigger':'action.click','workflow':{'workflow_id':'cib-launch-people','input':base},'result_to_state':'people'},{'event_id':'choose','trigger':'table.row_click','workflow':{'workflow_id':'cib-launch-people','input':{**base,'subject_user_id':'{{ event.payload.item.user_id }}'}},'result_to_state':'people'}]
    if form=='direction':
        for name,label in [('campagnes_accessibles',"Accessible campaigns"),('demandes_accessibles',"Accessible trial requests"),('premiers_resultats_confirmes',"First results attested")]:layout.append({'type':'section','title':label,'children':[{'type':'text','value':{'state':'listing.summary.'+name}}]})
    events.append({'event_id':'save','trigger':'form.submit','workflow':{'workflow_id':'cib-launch-'+MAP[form],'input':{n:'{{ state.'+n+' }}' for n in FIELDS[form]}},'result_to_state':'listing' if form=='direction' else 'selected'})
    properties={n:{'type':'string'} for n in sorted(set(defaults)|set(FIELDS[form]))};properties.update({n:{'type':'object'} for n in ['listing','selected','people']})
    return {'$schema':'agentmaurice.miniapp/v2','schema_version':2,'kind':'miniapp','miniapp_id':'cib-launch-'+form+'-console','version':'2','title':OPS[MAP[form]][0],'description':GUIDES[form],'ui':{'renderer':'component','component':'company-in-a-box','configuration':{'layout':layout}},'state_schema':{'type':'object','properties':properties},'initial_state':{**defaults,'listing':{'items':[],'message':"No list loaded.",'summary':{}},'selected':{'record':{},'prefill':defaults,'message':"No record selected."},'people':{'people':[]}},'events':events}
def build():
    for op in OPS:dump(DEST/'workflows'/('cib-launch-'+op+'.json'),workflow(op))
    for form in MAP:dump(DEST/'miniapps'/('cib-launch-'+form+'-console.json'),miniapp(form))
    manifest={'$schema':'agentmaurice.module/v2','schema_version':2,'key':'cib-marketing-launch','name':"Company in a Box — Launch Marketing",'version':'0.1.1','provides':{'actions':[],'queries':[],'apps':[]},'requires':{}}
    for op in OPS:manifest['provides']['queries' if op in ['read','list','people','summary'] else 'actions'].append({'key':op,'workflow_id':'cib-launch-'+op,'workflow_version':'2'})
    for form in MAP:manifest['provides']['apps'].append({'key':form,'miniapp_id':'cib-launch-'+form+'-console','miniapp_version':'2'})
    dump((ROOT.parents[1] / 'marketing-launch')/'module.yaml',manifest)
    cases=[]
    valid={'jeu':'qualification','campaign_id':'mkt-technical-denied','objectif':'Qualification','audience':"Synthetic",'promesse':"No public promise",'canal':'interne','responsable':'test','echeance':'2026-12-31','critere_fin':"Internal qualification",'expected_revision':'0','confirmation_manuelle':'oui'}
    for op,inp in [('campaign-save',valid),('read',{'jeu':'qualification','kind':'campaign','id':'mkt-technical-denied','form_id':'campaign'}),('list',{'jeu':'qualification','kind':'all'}),('summary',{'jeu':'qualification'})]:cases.append({'id':'launch-technical-denied-'+op,'description':"The broker must refuse technical execution without human identity; positive cases use CIB sessions.",'workflow':{'workflow_id':'cib-launch-'+op,'input':inp},'assertions':[{'type':'status','expected':'failed'}]})
    dump((ROOT.parents[1] / 'templates/company-in-a-box/tests/marketing-launch-plan.json'),{'$schema':'agentmaurice.test_plan/v2','schema_version':2,'test_plan_id':'cib-marketing-launch','cases':cases})
    dump(ROOT/'service-gates.json',{'workflows':{'cib-launch-'+op:role for op,(_,_,role) in OPS.items()}})
if __name__=='__main__':build()
